/**
 * The design-token boundary.
 *
 * This is the security-relevant part of "the site restyles itself". A variant may
 * be generated by a language model and served to the public without a human in the
 * loop, so what a variant is allowed to put into the page has to be constrained by
 * construction rather than by review.
 *
 * The constraint is: a variant carries CSS *custom-property values*, and nothing
 * else. It cannot open a declaration block, terminate one, start a comment, inject
 * markup, or call a CSS function that reaches the network or the DOM.
 *
 * WHY A FUNCTION ALLOWLIST RATHER THAN BANNING PARENTHESES
 * The first version of this file banned parentheses outright, which is airtight and
 * also useless: `var(--font-grotesk)`, `oklch(0.62 0.15 250)` and
 * `cubic-bezier(0.2, 0, 0, 1)` are all ordinary, necessary token values. Banning
 * them would push authors into hard-coded hex and magic numbers - a worse design
 * system defended by a rule nobody could follow. An allowlist of pure, side-effect-free
 * CSS functions gives the same guarantee without the collateral damage.
 *
 * `url()` and `image-set()` are deliberately absent: a token that can fetch is a
 * token that can exfiltrate. Media lives in a typed `src` field with its own
 * validation, not in the token bag.
 */

import { z } from 'zod';

/**
 * CSS functions a token value may call. Every one is pure: it computes a value from
 * its arguments and touches nothing outside the style system.
 */
export const ALLOWED_TOKEN_FUNCTIONS: ReadonlySet<string> = new Set([
  'var',
  'calc',
  'clamp',
  'min',
  'max',
  'round',
  'oklch',
  'oklab',
  'lch',
  'lab',
  'rgb',
  'rgba',
  'hsl',
  'hsla',
  'color-mix',
  'cubic-bezier',
  'steps',
  'linear-gradient',
  'radial-gradient',
  'conic-gradient',
  'repeating-linear-gradient',
]);

/** Characters that would let a value escape its declaration or open a comment. */
const FORBIDDEN_SEQUENCES: readonly (readonly [RegExp, string])[] = [
  [/[;{}]/, 'may not contain `;`, `{` or `}` - a token value cannot end or open a declaration'],
  [/[<>]/, 'may not contain angle brackets'],
  [/\\/, 'may not contain a backslash escape'],
  [/\/\*|\*\//, 'may not contain a CSS comment'],
  [/@/, 'may not contain an at-rule'],
  [/expression\s*\(/i, 'may not use the legacy `expression()` function'],
];

const FUNCTION_CALL = /([a-zA-Z][a-zA-Z0-9-]*)\s*\(/g;

/** Returns a list of problems, empty when the value is acceptable. */
export function tokenValueIssues(value: string): readonly string[] {
  const problems: string[] = [];

  for (const [pattern, message] of FORBIDDEN_SEQUENCES) {
    if (pattern.test(value)) problems.push(`Token value ${message}.`);
  }

  // `matchAll` on a fresh regex each call - a module-level /g regex carries
  // `lastIndex` between calls and would skip every other value.
  for (const match of value.matchAll(new RegExp(FUNCTION_CALL.source, 'g'))) {
    // eslint-disable-next-line @typescript-eslint/no-non-null-assertion -- FUNCTION_CALL always captures group 1
    const name = match[1]!.toLowerCase();
    if (!ALLOWED_TOKEN_FUNCTIONS.has(name)) {
      problems.push(`Token value may not call \`${name}()\`.`);
    }
  }

  const open = (value.match(/\(/g) ?? []).length;
  const close = (value.match(/\)/g) ?? []).length;
  if (open !== close) problems.push('Token value has unbalanced parentheses.');

  return problems;
}

/** Custom-property names: `--kebab-case`, 3 to 50 characters. */
export const TokenName = z
  .string()
  .regex(/^--[a-z][a-z0-9-]{1,48}$/, 'Token names must be CSS custom properties in kebab-case');

export const TokenValue = z
  .string()
  .min(1)
  .max(160)
  .superRefine((value, ctx) => {
    for (const message of tokenValueIssues(value)) {
      ctx.addIssue({ code: z.ZodIssueCode.custom, message });
    }
  });

export const TokenMap = z.record(TokenName, TokenValue);

export type Tokens = z.infer<typeof TokenMap>;

/**
 * Render a token bag as the inline `style` attribute value the server writes onto
 * `<html>`. This is the only place tokens become CSS text, and it re-validates
 * rather than trusting that whatever produced the bag already did.
 */
export function tokensToStyleAttribute(tokens: Tokens): string {
  const entries = Object.entries(tokens);
  for (const [name, value] of entries) {
    const nameCheck = TokenName.safeParse(name);
    if (!nameCheck.success) throw new Error(`Refusing to render invalid token name: ${name}`);
    const issues = tokenValueIssues(value);
    if (issues.length > 0) {
      throw new Error(`Refusing to render token ${name}: ${issues.join(' ')}`);
    }
  }
  return entries
    .sort(([a], [b]) => (a < b ? -1 : 1))
    .map(([name, value]) => `${name}:${value}`)
    .join(';');
}
